let activePillarId = 1;

function renderPillarButtons() {
    const container = document.getElementById('volume-pills-container');
    if (!container) return;

    let html = '';
    ENCYCLOPEDIA_DATA.forEach(p => {
        const isActive = p.id === activePillarId;
        const btnClass = isActive 
            ? 'bg-gold-500 text-cosmic-900 font-bold border border-gold-400 shadow-md shadow-gold-500/20' 
            : 'bg-cosmic-800 text-slate-300 hover:text-gold-400 hover:bg-cosmic-700 border border-slate-700/60';
        
        // short label
        let shortTitle = p.title.split('(')[0].trim();
        if (shortTitle.length > 22) shortTitle = shortTitle.substring(0, 20) + '...';

        html += `
            <button onclick="selectPillar(${p.id})" id="pillar-btn-${p.id}" class="px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all duration-200 shrink-0 font-hindi ${btnClass}">
                स्तंभ ${p.id}: ${shortTitle} (50 वाक्य)
            </button>
        `;
    });
    container.innerHTML = html;
}

function selectPillar(pillarId) {
    activePillarId = pillarId;
    renderPillarButtons();

    const pillar = ENCYCLOPEDIA_DATA.find(p => p.id === pillarId);
    if (pillar) {
        renderPillarSentences(pillar);
    }
}

function renderPillarSentences(pillar) {
    const container = document.getElementById('volume-content-display');
    if (!container) return;

    let html = `
        <div class="glass-card rounded-2xl p-6 md:p-8 space-y-4 border border-gold-500/30 mb-6">
            <div class="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <div class="flex items-center gap-2">
                        <span class="px-3 py-1 rounded-full text-xs font-bold bg-gold-500/20 text-gold-400 border border-gold-500/30">
                            स्तंभ ${pillar.id} / 20
                        </span>
                        <span class="px-3 py-1 rounded-full text-xs font-bold bg-emerald-500/20 text-emerald-400 border border-emerald-500/30">
                            ✓ 50 अद्वितीय, गैर-दोहराव वाक्य (100% Unique)
                        </span>
                    </div>
                    <h3 class="text-xl md:text-2xl font-bold text-white font-cinzel mt-2">${pillar.title}</h3>
                    <p class="text-xs text-amber-300/80 font-hindi mt-1"><strong>ज्योतिषीय आधार:</strong> ${pillar.astro_basis}</p>
                </div>
                <div class="flex items-center gap-2 shrink-0">
                    <button onclick="navigatePillar(-1)" class="px-3 py-1.5 rounded-lg bg-cosmic-800 border border-gold-500/30 text-xs font-bold text-gold-400 hover:bg-gold-500/10 font-hindi">
                        ← पिछला स्तंभ
                    </button>
                    <button onclick="navigatePillar(1)" class="px-3 py-1.5 rounded-lg bg-cosmic-800 border border-gold-500/30 text-xs font-bold text-gold-400 hover:bg-gold-500/10 font-hindi">
                        अगला स्तंभ →
                    </button>
                </div>
            </div>
        </div>

        <div class="glass-card rounded-2xl p-6 space-y-4 border border-slate-700/60">
            <div class="flex items-center justify-between border-b border-gold-500/20 pb-3">
                <h4 class="text-base font-bold text-gold-400 font-cinzel">
                    स्तंभ ${pillar.id} के सभी 50 सूक्ष्म भविष्यसूचक वाक्य (प्रत्यक्ष सूची — कोई सर्च नहीं):
                </h4>
                <span class="text-xs px-2.5 py-1 rounded-md bg-emerald-500/10 text-emerald-400 font-bold">
                    50 / 50 पूर्ण
                </span>
            </div>

            <div class="grid grid-cols-1 md:grid-cols-2 gap-3 mt-4">
    `;

    pillar.sentences.forEach((sent, sIdx) => {
        html += `
            <div class="p-3.5 rounded-xl bg-cosmic-900/70 border border-slate-800/90 text-xs text-slate-200 font-hindi leading-relaxed flex items-start gap-3 hover:border-gold-500/30 transition-all">
                <span class="inline-block w-6 h-6 rounded-full bg-gold-500/20 text-gold-400 text-xs font-bold text-center leading-6 shrink-0 mt-0.5 font-cinzel">
                    ${sIdx + 1}
                </span>
                <span class="leading-relaxed">${sent}</span>
            </div>
        `;
    });

    html += `
            </div>
        </div>
        
        <div class="flex justify-between items-center py-6 mt-6 border-t border-slate-700/60 font-hindi text-sm">
            <button onclick="navigatePillar(-1)" class="px-4 py-2 rounded-xl bg-cosmic-800 border border-gold-500/30 text-gold-400 hover:bg-gold-500/10">
                ← पिछला स्तंभ देखें
            </button>
            <span class="text-xs text-slate-400">स्तंभ ${pillar.id} / 20 (कुल 1,000 अद्वितीय वाक्य)</span>
            <button onclick="navigatePillar(1)" class="px-4 py-2 rounded-xl bg-cosmic-800 border border-gold-500/30 text-gold-400 hover:bg-gold-500/10">
                अगला स्तंभ देखें →
            </button>
        </div>
    `;

    container.innerHTML = html;
}

function navigatePillar(direction) {
    let nextId = activePillarId + direction;
    if (nextId < 1) nextId = 20;
    if (nextId > 20) nextId = 1;
    selectPillar(nextId);
}

function render500SummaryDirectList() {
    const container = document.getElementById('points-container');
    if (!container) return;

    let html = '';
    DOMAINS_DATA.forEach(domain => {
        html += `
            <div class="glass-card rounded-2xl p-6 space-y-4 mb-6">
                <div class="flex items-center gap-3 border-b border-gold-500/20 pb-3">
                    <span class="text-2xl">${domain.icon}</span>
                    <div>
                        <h3 class="text-lg md:text-xl font-bold text-gold-400 font-cinzel">${domain.title}</h3>
                        <p class="text-xs text-amber-300/70 font-hindi mt-0.5"><strong>ज्योतिषीय आधार:</strong> ${domain.astroBasis}</p>
                    </div>
                </div>
                <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
        `;

        domain.points.forEach(p => {
            html += `
                <div class="point-card p-4 rounded-xl bg-cosmic-800/60 border border-slate-700/50 hover:border-gold-500/40 transition-all">
                    <div class="flex items-start gap-3">
                        <span class="w-7 h-7 rounded-full bg-gold-500/20 text-gold-400 text-xs font-bold flex items-center justify-center shrink-0 mt-0.5 font-cinzel">${p.num}</span>
                        <div>
                            <h4 class="text-sm font-bold text-white font-hindi">${p.title}</h4>
                            <p class="text-xs text-slate-300 mt-1.5 font-hindi leading-relaxed">${p.desc}</p>
                        </div>
                    </div>
                </div>
            `;
        });

        html += `
                </div>
            </div>
        `;
    });

    container.innerHTML = html;
}

// Initialize on page load
document.addEventListener('DOMContentLoaded', () => {
    render500SummaryDirectList();
    renderPillarButtons();
    if (ENCYCLOPEDIA_DATA.length > 0) {
        renderPillarSentences(ENCYCLOPEDIA_DATA[0]);
    }
});
